"from pathlib import Path\nimport json,os,math,collections\nimport numpy as np,torch,torch.nn as nn\nEXP=Path('/workspace/ayb/experiments/dfe-unified-p3'); OUT=EXP/'geometry_probe'; RUN=Path(os.environ['GEOMETRY_RUN']); RUN.mkdir(exist_ok=False)\nrows=[json.loads(x) for x in (OUT/'geometry_features.jsonl').open() if x.strip()]\nlabels={r['code']:float(r['pk']) for r in json.loads((EXP/'refined_labels.json').read_text())}\nassert len(rows)==5316 and len(labels)==5316\nsplit=json.loads((EXP/'refined_split.json').read_text())['split']\nfor k,v in split.items(): assert len(v)=={'train':4049,'val':444,'test':823}[k]\nassert set(r['code'] for r in rows)==set(labels)\nbins=sorted({k for r in rows if r['split']=='train' for k in r['pair_hist']}); vi={k:i for i,k in enumerate(bins)}\ndef mat(rs, mode='real', seed=0):\n rng=np.random.default_rng(seed); order=rng.permutation(len(rs)) if mode=='perm' else np.arange(len(rs)); X=np.zeros((len(rs),len(bins)),np.float32); y=np.array([labels[r['code']] for r in rs],np.float32)\n for i,r in enumerate(rs):\n  source=rs[order[i]]\n  h=source['pair_hist']\n  if mode=='ligand_only':\n   h={k:v for k,v in h.items() if k.split(':')[0] in ('C','N','O','S','P','F','Cl','Br','I')}\n  elif mode=='pocket_only':\n   h={k:v for k,v in h.items() if k.split(':')[1] in ('C','N','O','S','P','F','Cl','Br','I')}\n  for k,v in h.items():\n   if k in vi:X[i,vi[k]]=math.log1p(v)\n  z=X[i].sum(); X[i]/=max(1.,z)\n return X,y\nsets={k:[r for r in rows if r['split']==k] for k in ['train','val','test']}\nclass M(nn.Module):\n def __init__(self,d):super().__init__();self.net=nn.Sequential(nn.Linear(d,128),nn.ReLU(),nn.Dropout(.1),nn.Linear(128,64),nn.ReLU(),nn.Linear(64,1))\n def forward(self,x):return self.net(x).squeeze(-1)\ndef pear(a,b):\n a=a-a.mean();b=b-b.mean();return float((a*b).sum()/(np.linalg.norm(a)*np.linalg.norm(b)+1e-9))\ndef fit(mode,seed):\n trX,try_=mat(sets['train'],mode,seed+1);vaX,vay=mat(sets['val'],mode,seed+2);teX,tey=mat(sets['test'],mode,seed+3)\n mu=trX.mean(0);sd=trX.std(0)+1e-6; ym=try_.mean();ys=try_.std()+1e-6\n trX=(trX-mu)/sd;vaX=(vaX-mu)/sd;teX=(teX-mu)/sd\n torch.manual_seed(seed);m=M(len(bins));opt=torch.optim.Adam(m.parameters(),lr=1e-3,weight_decay=1e-4);xt=torch.tensor(trX);yt=torch.tensor((try_-ym)/ys);xv=torch.tensor(vaX);xe=torch.tensor(teX);best=(-99,None,0)\n for ep in range(250):\n  m.train();opt.zero_grad();loss=((m(xt)-yt)**2).mean();assert torch.isfinite(loss);loss.backward();torch.nn.utils.clip_grad_norm_(m.parameters(),100.,error_if_nonfinite=True);opt.step();m.eval()\n  with torch.no_grad():pv=m(xv).numpy()*ys+ym\n  q=pear(pv,vay);assert math.isfinite(q)\n  if q>best[0]:best=(q,{k:v.detach().clone() for k,v in m.state_dict().items()},ep+1)\n m.load_state_dict(best[1]);m.eval()\n with torch.no_grad():pred=m(xe).numpy()*ys+ym\n return {'mode':mode,'seed':seed,'val_pearson':best[0],'test_pearson':pear(pred,tey),'test_rmse':float(np.sqrt(np.mean((pred-tey)**2))),'best_epoch':best[2],'n_train':len(try_),'n_val':len(vay),'n_test':len(tey)}\nres=[]\nfor mode in ['real','perm','ligand_only','pocket_only']:\n for seed in [20260915,20260916,20260917]:\n  r=fit(mode,seed);res.append(r);print(r,flush=True)\nagg={m:{k:float(np.mean([r[k] for r in res if r['mode']==m])) for k in ['val_pearson','test_pearson','test_rmse']} for m in ['real','perm','ligand_only','pocket_only']}\nresult={'protocol':'matched PDBBind atom-pair histogram controls','n_rows':len(rows),'splits':{k:len(v) for k,v in sets.items()},'feature_dim':len(bins),'runs':res,'aggregate':agg,'fallback_rows_included':676,'note':'permute pocket geometry independently within each split while retaining labels; ligand_only/pocket_only are marginal element-distance controls.'}\n(RUN/'metrics.json').write_text(json.dumps(result,indent=2,allow_nan=False));print(json.dumps(result,indent=2),flush=True);print('GEOMETRY_CONTROLS_DONE',flush=True)\n"